package cl.felipe.agrofrost.application.usecase;
import cl.felipe.agrofrost.application.port.*; import cl.felipe.agrofrost.domain.entity.Field; import cl.felipe.agrofrost.domain.exception.FieldNotFoundException; import cl.felipe.agrofrost.domain.model.FrostRiskLevel; import cl.felipe.agrofrost.domain.repository.FieldRepository; import cl.felipe.agrofrost.domain.valueobject.*; import org.junit.jupiter.api.*; import org.mockito.*; import java.util.Optional; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
class MonitorFieldUseCaseTest { @Mock FieldRepository repository; @Mock TemperatureProvider temperatureProvider; @Mock FrostAlertNotifier notifier; @InjectMocks MonitorFieldUseCase useCase; private final FieldId id=new FieldId("f-1"); private final Field field=new Field(id,new FieldName("North"),new Crop("Grapes"),new CriticalTemperature(0)); MonitorFieldUseCaseTest() { MockitoAnnotations.openMocks(this); } @Test void sendsOneAlertForCriticalRisk() { when(repository.findById(id)).thenReturn(Optional.of(field)); when(temperatureProvider.getCurrentTemperature(id)).thenReturn(new MeasuredTemperature(0)); FrostAssessment assessment=useCase.execute(id); assertEquals(FrostRiskLevel.CRITICAL, assessment.riskLevel()); verify(temperatureProvider).getCurrentTemperature(id); verify(notifier, times(1)).sendCriticalAlert(assessment); } @Test void doesNotAlertForWarningOrSafeRisk() { when(repository.findById(id)).thenReturn(Optional.of(field)); when(temperatureProvider.getCurrentTemperature(id)).thenReturn(new MeasuredTemperature(1)); assertEquals(FrostRiskLevel.WARNING, useCase.execute(id).riskLevel()); when(temperatureProvider.getCurrentTemperature(id)).thenReturn(new MeasuredTemperature(3)); assertEquals(FrostRiskLevel.SAFE, useCase.execute(id).riskLevel()); verify(notifier, never()).sendCriticalAlert(any()); } @Test void failsBeforeExternalCallsWhenFieldIsAbsent() { when(repository.findById(id)).thenReturn(Optional.empty()); assertThrows(FieldNotFoundException.class, () -> useCase.execute(id)); verifyNoInteractions(temperatureProvider, notifier); } @Test void rejectsNullDependenciesIdAndProviderTemperature() { assertAll(() -> assertThrows(NullPointerException.class, () -> new MonitorFieldUseCase(null, temperatureProvider, notifier)), () -> assertThrows(NullPointerException.class, () -> new MonitorFieldUseCase(repository, null, notifier)), () -> assertThrows(NullPointerException.class, () -> new MonitorFieldUseCase(repository, temperatureProvider, null)), () -> assertThrows(NullPointerException.class, () -> useCase.execute(null))); when(repository.findById(id)).thenReturn(Optional.of(field)); when(temperatureProvider.getCurrentTemperature(id)).thenReturn(null); assertThrows(NullPointerException.class, () -> useCase.execute(id)); } }
